/// Short hint for where a temperature sits between warm and cool.
fn temperature_hint(kelvin: u32) -> &'static str {
    match kelvin {
        ..=2699 => "Very warm",
        2700..=3999 => "Warm",
        4000..=5199 => "Neutral warm",
        _ => "Cool",
